import {CATEGORIES,pennies,upsert,remove,summarise,validateState,persist,demoState} from './core.mjs';
const $=s=>document.querySelector(s);const money=n=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'}).format(n/100);const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={version:1,transactions:[],budgets:{}},editId=null,charts=[],filter={search:'',type:'all',sort:'newest'};
const now=new Date();let month=now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0');$('#month').value=month;
try{const raw=localStorage.getItem('budgetwise.v1');if(raw)state=validateState(JSON.parse(raw));}catch(e){warning('Saved data could not be loaded. Export or preserve any existing backup before making changes. '+e.message);}
function warning(message){$('#storage-warning').textContent=message;$('#storage-warning').hidden=false;}
function announce(s){$('#status').textContent='';requestAnimationFrame(()=>$('#status').textContent=s);}
function save(next){try{state=persist(localStorage,next);$('#storage-warning').hidden=true;return true;}catch(e){warning('Changes were not saved. Your previous data is unchanged. '+e.message);return false;}}
function confirmAction(title,message,fn){const d=$('#confirm');$('#confirm-title').textContent=title;$('#confirm-message').textContent=message;d.returnValue='';d.onclose=()=>{if(d.returnValue==='ok')fn();};d.showModal();}
const typeName=t=>({income:'Income',needs:'Need',wants:'Want'}[t]);
function metric(label,value,sub,icon,featured=false){return `<article class="metric ${featured?'featured':''}"><div class="metric-label">${label}<i aria-hidden="true">${icon}</i></div><div class="metric-value ${value<0?'negative':''}">${money(value)}</div><small>${sub}</small></article>`;}
function metrics(s){return `<div class="metrics">${metric('Remaining balance',s.balance,'Income minus recorded expenses','↗',true)}${metric('Total income',s.income,'All income recorded this month','↓')}${metric('Total expenses',s.expenses,'Needs + wants for this month','↑')}</div>`;}
function table(rows,actions=false){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Description</th><th>Category</th><th>Date</th><th>Type</th><th class="amount">Amount</th>${actions?'<th>Actions</th>':''}</tr></thead><tbody>${rows.map(t=>`<tr><td><div class="transaction-name">${escape(t.description||t.category)}</div></td><td>${escape(t.category)}</td><td>${escape(t.date.slice(8)+'/'+t.date.slice(5,7))}</td><td><span class="badge ${t.type}">${typeName(t.type)}</span></td><td class="amount ${t.type==='income'?'income-amount':''}">${t.type==='income'?'+':'−'}${money(t.amount)}</td>${actions?`<td><button class="icon-button" data-edit="${escape(t.id)}" aria-label="Edit ${escape(t.description||t.category)}">Edit</button><button class="icon-button" data-delete="${escape(t.id)}" aria-label="Delete ${escape(t.description||t.category)}">Delete</button></td>`:''}</tr>`).join('')}</tbody></table></div>`:`<div class="empty"><h3>No transactions here yet.</h3><p>Add your first transaction or try another month.</p><a href="#add" class="button secondary">Add transaction</a></div>`;}
function chartPanel(id,title,subtitle){return `<article class="panel"><div class="panel-head"><div><h2>${title}</h2><p>${subtitle}</p></div><span class="small-label">MONTHLY VIEW</span></div><div class="chart-layout"><div class="chart-space"><canvas id="${id}" role="img" aria-label="${title}; exact amounts listed beside the chart"></canvas></div><div class="legend" id="${id}-legend"></div></div><p class="insight-note">Needs cover essentials. Wants are discretionary purchases.</p></article>`;}
function drawDonut(id,s){const colors=['#a9cd90','#a99be2'];const vals=[s.needs,s.wants];$('#'+id+'-legend').innerHTML=['Needs','Wants'].map((n,i)=>`<div class="legend-row"><span><i class="dot" style="background:${colors[i]}"></i>${n}</span><strong>${money(vals[i])}</strong></div>`).join('')+`<div class="legend-row"><span>Total spent</span><strong>${money(s.expenses)}</strong></div>`;
 if(window.Chart){charts.push(new Chart($('#'+id),{type:'doughnut',data:{labels:['Needs','Wants'],datasets:[{data:s.expenses?vals:[1,0],backgroundColor:s.expenses?colors:['#edf0e8','#edf0e8'],borderWidth:0,borderRadius:s.expenses?3:0,spacing:s.expenses?4:0}]},options:{responsive:true,maintainAspectRatio:false,cutout:'76%',plugins:{legend:{display:false},tooltip:{enabled:!!s.expenses,callbacks:{label:c=>c.label+': '+money(c.raw)}}}}}));}
 else{$('#'+id).outerHTML=`<div role="img" aria-label="Spending breakdown" style="width:160px;height:160px;border-radius:50%;margin:10px auto;background:conic-gradient(#a9cd90 0 ${s.expenses?s.needs/s.expenses*100:0}%,#a99be2 0);border:28px solid transparent;box-shadow:inset 0 0 0 100px white"></div>`;}
}
function progressRow(c,spent,budget,purple=false){const set=budget>0,ratio=set?Math.min(100,spent/budget*100):0;return `<div class="budget-item"><div class="budget-line"><strong>${escape(c)}</strong><span>${money(spent)} ${set?' / '+money(budget):' · no limit set'}</span></div><div class="bar ${set&&spent>budget?'over':purple?'purple':''}"><span style="width:${ratio}%"></span></div>${set&&spent>budget?'<div class="subtle negative">Over budget by '+money(spent-budget)+'</div>':''}</div>`;}
function dashboard(){const s=summarise(state.transactions,month),b=state.budgets[month]||{};$('#dashboard').innerHTML=(!state.transactions.length?`<div class="welcome"><div><strong>Your fresh start begins here.</strong><p>Add your own figures, or explore with clearly labelled example transactions.</p></div><button class="button secondary" data-demo>Explore example data</button></div>`:'')+metrics(s)+`<div class="grid-two">${chartPanel('overview-chart','Where your money goes','Essential and discretionary spending')}<article class="panel"><div class="panel-head"><div><h2>Keep your plans in sight.</h2><p>Category budgets, one step at a time.</p></div></div>${['Groceries','Dining out','Shopping'].map((c,i)=>progressRow(c,s.categories[c],b[c],i>0)).join('')}<a href="#budgets" class="panel-link">Manage monthly budgets ↗</a></article></div><article class="panel"><div class="panel-head"><div><h2>Recent activity</h2><p>Your latest recorded transactions</p></div><a href="#transactions" class="text-button">View all ↗</a></div>${table([...s.rows].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5))}</article>`;drawDonut('overview-chart',s);}
function renderForm(){const t=state.transactions.find(t=>t.id===editId);if(!t)editId=null;$('#add').innerHTML=`<div class="form-layout"><article class="panel"><div class="panel-head"><div><h2>${t?'Edit transaction':'Every entry adds clarity.'}</h2><p>Record income or an expense. All amounts are in GBP.</p></div></div><form id="transaction-form"><div class="form-grid"><label class="field">Transaction type<select id="type" required><option value="needs">Expense · Need</option><option value="wants">Expense · Want</option><option value="income">Income</option></select></label><label class="field">Category<select id="category" required></select></label><label class="field">Amount (£)<input id="amount" inputmode="decimal" type="text" required placeholder="0.00" maxlength="11"><small>Enter a positive amount, e.g. 24.50</small></label><label class="field">Date<input id="date" type="date" required min="1900-01-01" max="9999-12-31"></label><label class="field wide">Description <span class="subtle">Optional</span><input id="description" type="text" maxlength="120" placeholder="e.g. Weekly grocery shop"></label></div><div id="form-error" class="notice error" role="alert" hidden></div><div class="form-actions"><button class="button primary" type="submit">${t?'Save changes':'Save transaction'}</button><a class="button secondary" href="#transactions">Cancel</a></div></form></article><aside class="tip-panel"><p class="eyebrow">MAKE IT A HABIT</p><h2>Small entries.<br>A bigger picture.</h2><p>Record purchases as you go, so your monthly overview stays useful.</p><ul><li>Needs: housing, groceries and essentials.</li><li>Wants: dining out, hobbies and extras.</li><li>Income: salary, freelance work and more.</li></ul><p>Your data stays in this browser. Export a backup to keep a separate copy.</p></aside></div>`;
 const fill=selected=>{$('#category').innerHTML=CATEGORIES[$('#type').value].map(c=>`<option>${c}</option>`).join('');if(selected)$('#category').value=selected;};$('#type').value=t?.type||'needs';fill(t?.category);$('#type').onchange=()=>fill();$('#amount').value=t?(t.amount/100).toFixed(2):'';$('#date').value=t?.date||(month+'-'+String(month===now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0')?now.getDate():1).padStart(2,'0'));$('#description').value=t?.description||'';
 $('#transaction-form').onsubmit=e=>{e.preventDefault();try{const transaction={id:editId||crypto.randomUUID(),type:$('#type').value,category:$('#category').value,amount:pennies($('#amount').value),date:$('#date').value,description:$('#description').value};const next={...state,transactions:upsert(state.transactions,transaction)};if(save(next)){editId=null;month=transaction.date.slice(0,7);$('#month').value=month;location.hash='transactions';announce('Transaction saved.');}}catch(err){$('#form-error').hidden=false;$('#form-error').textContent=err.message;}};
}
function renderTransactions(){const s=summarise(state.transactions,month);$('#transactions').innerHTML=`<article class="panel"><div class="panel-head"><div><h2>Transaction history</h2><p>Review and update your monthly records.</p></div><span class="small-label">${s.rows.length} ENTRIES</span></div><div class="filter-row"><input id="search" type="search" placeholder="Search descriptions or categories" aria-label="Search transactions" value="${escape(filter.search)}"><select id="type-filter" aria-label="Filter transaction type"><option value="all">All types</option><option value="income">Income</option><option value="needs">Needs</option><option value="wants">Wants</option></select><select id="sort" aria-label="Sort transactions"><option value="newest">Newest first</option><option value="oldest">Oldest first</option><option value="largest">Largest amount</option></select></div><div id="transaction-results"></div></article>`;$('#type-filter').value=filter.type;$('#sort').value=filter.sort;const update=()=>{filter={search:$('#search').value,type:$('#type-filter').value,sort:$('#sort').value};let rows=s.rows.filter(t=>(filter.type==='all'||t.type===filter.type)&&(t.description+' '+t.category).toLowerCase().includes(filter.search.toLowerCase()));rows.sort((a,b)=>filter.sort==='largest'?b.amount-a.amount:filter.sort==='newest'?b.date.localeCompare(a.date):a.date.localeCompare(b.date));$('#transaction-results').innerHTML=table(rows,true);};$('#search').oninput=update;$('#type-filter').onchange=update;$('#sort').onchange=update;update();}
function renderBudgets(){const s=summarise(state.transactions,month),b=state.budgets[month]||{};$('#budgets').innerHTML=`<div class="stat-note"><h2>A plan that fits your life.</h2><p>Set your own category limits. Blank or zero means no limit. Budgets are saved separately for each month.</p></div><form id="budget-form"><div class="budget-grid">${['needs','wants'].map(type=>`<article class="panel"><div class="panel-head"><div><h2>${type==='needs'?'Essential needs':'Discretionary wants'}</h2><p>Monthly limits in GBP (£)</p></div></div>${CATEGORIES[type].map((c,i)=>`<div class="budget-input-row"><div><label for="budget-${type}-${i}">${c}</label><div class="subtle">Spent ${money(s.categories[c])}</div></div><input id="budget-${type}-${i}" data-budget="${c}" aria-label="${c} monthly budget in pounds" inputmode="decimal" value="${b[c]?(b[c]/100).toFixed(2):''}" placeholder="No limit"></div>`).join('')}</article>`).join('')}</div><div id="budget-error" class="notice error" role="alert" hidden></div><div class="form-actions"><button class="button primary" type="submit">Save monthly budgets</button><span class="subtle">Current income: ${money(s.income)}</span></div></form><article class="panel" style="margin-top:22px"><div class="panel-head"><h2>Budget versus actual</h2></div>${Object.entries(b).filter(([,n])=>n>0).map(([c,n])=>progressRow(c,s.categories[c],n,CATEGORIES.wants.includes(c))).join('')||'<p class="subtle">Set a category limit above to see your progress.</p>'}</article>`;$('#budget-form').onsubmit=e=>{e.preventDefault();try{const limits={};document.querySelectorAll('[data-budget]').forEach(el=>{limits[el.dataset.budget]=!el.value.trim()||/^0(?:\.0{1,2})?$/.test(el.value.trim())?0:pennies(el.value);});if(save({...state,budgets:{...state.budgets,[month]:limits}})){renderBudgets();announce('Monthly budgets saved.');}}catch(err){$('#budget-error').textContent=err.message;$('#budget-error').hidden=false;}};}
function renderInsights(){const s=summarise(state.transactions,month);const top=Object.entries(s.categories).sort((a,b)=>b[1]-a[1]);$('#insights').innerHTML=metrics(s)+`<div class="grid-two">${chartPanel('insight-chart','Needs and wants','Understand your spending mix')}<article class="panel"><div class="panel-head"><h2>Your monthly perspective</h2></div><h2 style="font-size:30px;margin:20px 0 10px">${s.income?(s.expenses/s.income*100).toFixed(1)+'%':'—'}</h2><p>of recorded income spent</p><p class="insight-note">${s.expenses?`Your largest spending category is <strong>${escape(top[0][0])}</strong> at ${money(top[0][1])}.`:'Add expenses to reveal your largest spending category.'}</p><p class="insight-note">A remaining balance is unspent income, not confirmed savings. Needs and wants are budgeting categories, not environmental impact scores.</p></article></div><article class="panel"><div class="panel-head"><div><h2>Category breakdown</h2><p>Exact values behind the chart</p></div></div><table class="insight-table"><thead><tr><th>Category</th><th>Group</th><th class="amount">Spent</th><th class="amount">% of expenses</th></tr></thead><tbody>${top.map(([c,n])=>`<tr><td>${escape(c)}</td><td>${CATEGORIES.needs.includes(c)?'Needs':'Wants'}</td><td class="amount">${money(n)}</td><td class="amount">${s.expenses?(n/s.expenses*100).toFixed(1)+'%':'—'}</td></tr>`).join('')}</tbody></table></article>`;drawDonut('insight-chart',s);}
const pages={dashboard:['Your month, at a glance.','Know where you stand. Choose what comes next.',dashboard,'Overview'],add:['One entry. More clarity.','Keep your income and spending in one place.',renderForm,'Add transaction'],transactions:['Every transaction, together.','Find the details behind your monthly picture.',renderTransactions,'Transactions'],budgets:['Give your money a plan.','Set flexible limits for the things that matter.',renderBudgets,'Monthly budgets'],insights:['See the bigger picture.','Turn everyday entries into useful perspective.',renderInsights,'Spending insights']};
function render(){charts.forEach(c=>c.destroy());charts=[];let key=location.hash.slice(1)||'dashboard';if(!pages[key])key='dashboard';const [title,sub,fn,crumb]=pages[key];$('.page-heading .primary').hidden=key==='add';$('#page-title').textContent=title;$('#page-subtitle').textContent=sub;$('#crumb').textContent=crumb;document.title=crumb+' · BudgetWise';document.querySelectorAll('.page').forEach(el=>el.hidden=el.id!==key);document.querySelectorAll('[data-page]').forEach(el=>{el.classList.toggle('active',el.dataset.page===key);if(el.dataset.page===key)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});fn();}
window.addEventListener('hashchange',()=>{if(location.hash!=='#add')editId=null;render();$('#main').focus({preventScroll:true});});$('#month').onchange=()=>{if(!/^\d{4}-(0[1-9]|1[0-2])$/.test($('#month').value))return;month=$('#month').value;render();};
function demo(){confirmAction('Load example data?','This replaces the current records with an example monthly budget. Export a backup first if you want to keep your entries.',()=>{if(save(demoState(month))){render();announce('Example transactions loaded.');}});}$('#load-demo').onclick=demo;
document.addEventListener('click',e=>{const el=e.target.closest('[data-demo],[data-edit],[data-delete]');if(!el)return;if(el.hasAttribute('data-demo'))demo();if(el.dataset.edit){editId=el.dataset.edit;if(location.hash==='#add')render();else location.hash='add';}if(el.dataset.delete){const id=el.dataset.delete;confirmAction('Delete transaction?','This entry will be removed and your totals will update.',()=>{if(save({...state,transactions:remove(state.transactions,id)})){render();announce('Transaction deleted.');}});}});
$('#clear').onclick=()=>confirmAction('Clear all data?','This permanently removes all transactions and monthly budgets from this browser. Export a backup first if you need a copy.',()=>{if(save({version:1,transactions:[],budgets:{}})){editId=null;render();announce('All data cleared.');}});
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='budgetwise-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);announce('Backup exported.');};
$('#import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10000000)throw Error('Backup must be smaller than 10 MB.');const next=validateState(JSON.parse(await file.text()));confirmAction('Import backup?','This will replace all current transactions and budgets with the selected backup.',()=>{if(save(next)){render();announce('Backup imported.');}});}catch(err){warning('Import was not completed: '+err.message);}e.target.value='';};
window.addEventListener('storage',e=>{if(e.key==='budgetwise.v1')warning('Data changed in another tab. Reload this page before editing to avoid overwriting those changes.');});render();
